const express = require('express');
const puppeteer = require('puppeteer');
const { Sequelize, DataTypes } = require('sequelize');

const app = express();
app.use(express.json());
const sequelize = new Sequelize(process.env.DB_URI);

const CrawlerJob = sequelize.define('CrawlerJob', {
  id: { type: DataTypes.UUID, primaryKey: true },
  companyId: DataTypes.UUID,
  targetPortalUrl: DataTypes.STRING,
  vaultCredentialId: DataTypes.STRING
});

app.post('/api/crawlers/run', async (req, res) => {
  const { crawlerConfigId } = req.body;

  // Enforce company scoping when retrieving crawler job
  const job = await CrawlerJob.findOne({
    where: {
      id: crawlerConfigId,
      companyId: req.user.companyId
    }
  });
  if (!job) {
    return res.status(404).json({ error: 'Crawler job configuration not found' });
  }

  // Decrypt crawler credentials stored in vault for portal automation
  const credentials = await fetchVaultSecret(job.vaultCredentialId);

  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto(job.targetPortalUrl);
  await page.type('#username', credentials.username);
  await page.type('#password', credentials.password);
  await page.click('#login-button');
  await page.waitForNavigation();

  const extractedData = await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll('.statement-row'));
    return rows.map(r => r.innerText);
  });

  await browser.close();
  return res.json({ jobId: job.id, extractedData });
});

module.exports = app;
